// src/content/oss.ts
// Typed access to the upstream contribution snapshot in oss-data.json.
//
// The JSON is generated by scripts/fetch-oss.mjs and committed. Nothing here
// invents or rounds anything: every row came from the GitHub search API, and
// `fetchedAt` says when.

import raw from "./oss-data.json";

export type PrState = "merged" | "open" | "closed";

export type OssPr = {
  number: number;
  title: string;
  url: string;
  state: PrState;
  created: string;
  closedAt: string | null;
};

export type OssRepo = {
  full: string;
  owner: string;
  name: string;
  slug: string;
  merged: number;
  open: number;
  closed: number;
  prs: OssPr[];
};

export type OssData = {
  user: string;
  fetchedAt: string;
  note: string;
  totals: { merged: number; open: number; closed: number; prs: number };
  repoCount: number;
  repos: OssRepo[];
};

export const oss = raw as OssData;

/** Repos with at least one merged PR, best first. These are the record. */
export const mergedRepos: OssRepo[] = oss.repos.filter((r) => r.merged > 0);

/** Everything else: open or closed, nothing landed yet. */
export const pendingRepos: OssRepo[] = oss.repos.filter((r) => r.merged === 0);

export function getRepo(slug: string): OssRepo | undefined {
  return oss.repos.find((r) => r.slug === slug);
}

export function repoSlugs(): string[] {
  return oss.repos.map((r) => r.slug);
}

/**
 * Hand-written context for a project, shown on its page above the PR list.
 * Deliberately sparse: a repo with nothing written about it shows only the
 * verified PR list, which is still true. An invented description of what
 * cilium does would be worse than none.
 */
export const REPO_NOTES: Record<string, string> = {};

/**
 * Contribution tiers (ATZOSS v2, source cnc/OSS/TIERS.md, hand-checked 7 Nov 2026).
 * Level is objective, computed from the merged count in a repo: one is drive-by,
 * two to four recurring, five or a shipped feature is trusted. A point-in-time
 * snapshot of the 47 merged third-party pull requests, not a live figure.
 */
export type ContributionTier = {
  level: string;
  label: string;
  meaning: string;
  merges: number;
  repoCount: number;
  examples: string[];
};

export const tierSnapshot = "7 Nov 2026";

export const contributionTiers: ContributionTier[] = [
  { level: "L1", label: "Drive-by", meaning: "a single fix a maintainer took", merges: 15, repoCount: 15, examples: [] },
  { level: "L2", label: "Recurring", meaning: "work taken more than once", merges: 26, repoCount: 9, examples: ["openswap", "podman", "otel python-contrib", "braidpool", "meshery", "kmesh"] },
  { level: "L3", label: "Trusted", meaning: "five or more merges, or a shipped feature", merges: 6, repoCount: 1, examples: ["fedimint"] },
  { level: "L4", label: "Maintainer-track", meaning: "triage or write access inside a project", merges: 0, repoCount: 0, examples: [] },
];

export const contributionKinds = "43 fixes, 3 docs, 1 infra, no features yet";
